INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'mamelodi-court-construction-resumes-2026-10-30',
  'Mamelodi Magistrate''s Court construction restarts after years of delay',
  'Community', '2026-10-30', 'SAnews', 'https://www.sanews.gov.za/south-africa/work-mamelodi-magistrates-court-construction-resumes',
  'Work has resumed on the long-delayed Mamelodi Magistrate''s Court after a new contractor took over, with completion now due in October 2028.',
  'Construction has restarted at the Mamelodi Magistrate''s Court after years of delay that left the Tsamaya Road building unfinished. Planning for the court began in 2007 and a construction contract was awarded in 2013, with the facility originally due to open in 2016. The Department of Public Works and Infrastructure terminated that contract in October 2023, citing poor performance by the contractor and repeated stoppages linked to so-called construction mafia groups, after roughly 60% of the building had been completed.

A new contractor has returned to the site, and work resumed on 7 October 2026. Dean Macpherson, the minister of public works and infrastructure, together with Deputy Chief Justice Mlambo, inspected progress at the site on Thursday. At R241.26 million including VAT, the fresh contract covers a 24-month building programme, which puts the project''s finish date at October 2028.

The department says it is now managing the project directly so it can monitor progress and resolve problems early, and is using a community engagement framework meant to head off the kind of job and subcontracting disputes that disrupted the earlier contract. Mlambo said the building''s condition meant it could be finished before the two-year deadline, and that he would return to the site in six months to check on progress. The department is also pursuing legal steps to recover losses caused by the earlier contractor''s failure to finish the work.',
  NULL, NULL, NULL,
  '["https://www.sanews.gov.za/south-africa/work-mamelodi-magistrates-court-construction-resumes", "https://www.enca.com/news/mamelodi-magistrates-court-construction-resumes-after-10-year-delay", "https://www.citizen.co.za/news/mamelodi-magistrates-court-back-on-track-despite-construction-mafia-delays/"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'bulls-beat-scarlets-54-26-loftus-2026-10-31',
  'Bulls run away late to beat Scarlets 54-26 at Loftus',
  'Sport', '2026-10-31', 'The Citizen', 'https://www.citizen.co.za/sport/rugby/urc-result-bulls-leave-it-late-to-down-scarlets/',
  'The Bulls scored a string of late tries to beat the Scarlets 54-26 in a United Rugby Championship match at Loftus Versfeld on Saturday.',
  'The Bulls beat the Scarlets 54-26 in a United Rugby Championship match at Loftus Versfeld on Saturday, pulling clear with a string of late tries after a tight contest. Eoghan Cross refereed the match, which was shown live on SuperSport.

The home side raced into an early 19-0 lead, but the Scarlets fought their way back into the game and the scoreline stayed close for close to an hour. Dylan Maart and Marcell Coetzee each scored two tries, with Sebastian de Klerk and replacement hooker Johan Grobbelaar also crossing the line. Flyhalf Curwin Bosch kicked well throughout, and Scarlets centre Stedman Gans was shown a yellow card for a careless trip.

The win was the Bulls'' fourth in five matches so far this URC season and keeps them in the top half of the table.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/sport/rugby/urc-result-bulls-leave-it-late-to-down-scarlets/", "https://rugby365.com/live/bulls-vs-scarlets/?g=421220"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'tshwane-spca-appeals-clean-water-dogs-ill-2026-10-28',
  'Tshwane SPCA appeals for clean water as more than 100 dogs fall ill',
  'Community', '2026-10-28', 'Rekord', 'https://www.citizen.co.za/rekord/news-headlines/local-news/2026/10/28/tshwane-spca-appeals-for-clean-drinking-water-as-illness-hits-kennels/',
  'More than 100 dogs at the Tshwane SPCA''s Centurion and Waltloo branches have fallen ill, and the organisation is appealing for donations of clean drinking water.',
  'More than 100 dogs at the Tshwane SPCA have fallen ill with diarrhoea, vomiting and lethargy, and the organisation is appealing to the public for donations of clean drinking water. Staff initially suspected parvovirus, but tests came back negative. After ruling out the animals'' food, the SPCA identified its own water supply as the likely cause.

As a precaution, the SPCA is now giving the animals filtered or borehole water while samples from its facilities are tested to confirm the source of the contamination. Adoptions and public visits have been suspended at the affected branch while the investigation continues. The organisation is asking for donations of clean, purified or boiled-and-cooled drinking water, along with empty containers it can disinfect and fill itself. Donations can be dropped off at its Waltloo branch on Petroleum Street or its Centurion branch on Kruger Avenue in Lyttelton Manor, or collection can be arranged for people who cannot deliver them. Financial donations to help buy safe water and cover veterinary costs are also welcome.

The SPCA has urged pet owners elsewhere in the city to consult a vet immediately if their own animals show similar symptoms, and to keep affected animals hydrated in the meantime.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/rekord/news-headlines/local-news/2026/10/28/tshwane-spca-appeals-for-clean-drinking-water-as-illness-hits-kennels/", "https://www.getaway.co.za/news/more-than-100-dogs-fall-ill-after-contaminated-water-at-centurion-spca/"]',
  'agent'
);
